<template>
  <div class="px-4">
    <div class="text-h5 pt-8 pb-2">
      <b>My Wishlist</b>
    </div>
    <div class="d-flex align-center ga-2 my-4">
      <AdminCoreSearch :search="search" @search="setSearch" />

      <div class="">
        <v-btn class="text-caption card-outlined rounded-lg" variant="text" size="small" id="sortBy"
          prepend-icon="mdi-sort">
          <span>Sort by {{ String(sort).toLowerCase() }}</span>
        </v-btn>
        <AdminCoreSelect activator="#sortBy" :list="['Newest', 'Oldest', 'Big expense', 'Small expense']"
          :list-value="sort" @set-item="setSort" />
      </div>
    </div>
    <div class="d-flex flex-column ga-4 mt-8">
      <v-card class="card-outlined" flat v-for="product in filteredProducts" :key="product.id">
        <ClientShopProductCardsFullList :product="product" :wishlist="true" @toggle-wish-list="getData" />
      </v-card>
      {{ data.value }}
      <div class="py-10 my-10 py-md-15 my-md-15 text-disabled text-center" v-if="!filteredProducts.length || loading">
        <span v-if="loading">Loading orders...</span>
        <span v-else>No product found</span>
      </div>
    </div>
  </div>
</template>

<script setup>
const {
  currencyFormat,
  capitalizeFirstLetter,
  filterDataPerField,
  dateFormat_Month,
  numberFormat,
} = useHelpers();

import { useAppStore } from "~/store/app";
const { loading } = storeToRefs(useAppStore());

import { useSavedItemStore } from "~/store/saved-items";
const { wishlists } = useSavedItemStore();
const data = ref([]);
const getData = async () => {
  //
  data.value = await wishlists();
  //
};
watchEffect(() => {
  getData();
});

const sort = ref("Newest");
const setSort = (val) => {
  sort.value = val;
};
const search = ref("");
const setSearch = (val) => {
  search.value = val;
};
const filteredProducts = computed(() => {
  const unsortedData = filterDataPerField(data.value, search.value);
  if (sort.value === "Newest" || sort.value === "Oldest")
    return unsortedData.sort((a, b) => {
      if (a.dateCreated > b.dateCreated)
        if (sort.value === "Newest") return -1;
        else return 1;
    });
  if (sort.value === "Big expense" || sort.value === "Small expense")
    return unsortedData.sort((a, b) => {
      if (a.total > b.total) {
        if (sort.value === "Big expense") return -1;
        else return 1;
      }
    });
});

useHead({
  title: "My wishlist",
});
</script>

<style lang="css" scoped></style>
